import {analyzeSession} from './music-industry/analysis.js';import {analyzeStructure} from './music-industry/structure.js';import {analyzeHarmony} from './music-industry/harmony.js';import {analyzeGroove} from './music-industry/groove.js';import {analyzeStereo,spectrum} from './music-industry/analyzers.js';import {assessProfile} from './music-industry/profiles.js';import {measureLoudness} from './audio-loudness.js';import {measureAudio,auditRouting} from './audio-certification.js';
export function studioAR(project){const analysis=analyzeSession(project);const notes=[];for(const t of project.tracks){if(t.mute)continue;for(const c of t.clips||[]){if(c.muted||!Number.isFinite(c.start))continue;for(const n of c.notes||[])if(Number.isFinite(n.step))notes.push({...n,step:c.start*16+n.step});}}return {analysis,structure:project.sections?.length?analyzeStructure(project):null,harmony:analyzeHarmony(notes),groove:analyzeGroove(project)};}
export async function studioMaster(project,render,profile='streaming'){const issues=auditRouting(project);if(issues.length)throw Error(issues.join('; '));const b=await render(project),basic=measureAudio(b);if(basic.invalid)throw Error('PCM non fini');const loud=measureLoudness(b),stereo=analyzeStereo(b);return {basic,loud,stereo,profile:assessProfile(loud,profile),spectrum:b.length>=1024?spectrum(b,1024,Math.floor((b.length-1024)/2)):[],normativeCertified:false};}